const fs=require('fs'),path=require('path'),assert=require('node:assert/strict')
const ts=require('typescript'),Module=require('node:module')
const filename=path.join(process.cwd(),'lib/wvetroBarrasPdfServer.ts')
const code=ts.transpileModule(fs.readFileSync(filename,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020,esModuleInterop:true}}).outputText
const mod=new Module(filename,module);mod.filename=filename;mod.paths=Module._nodeModulePaths(path.dirname(filename));mod._compile(code,filename)
const {analisarPdfBarrasWVetro}=mod.exports
const pdfPath=process.env.WVETRO_BARRAS_FIXTURE||'/tmp/atlas-wvetro-barras-872-autenticado.pdf'
async function run(){
 if(fs.existsSync(pdfPath)){
  const r=await analisarPdfBarrasWVetro(fs.readFileSync(pdfPath))
  assert.equal(r.numeroOrcamento,'872')
  assert.equal(r.itens.length,18)
  assert.equal(r.itens.reduce((s,x)=>s+x.quantidade,0),31)
  assert.equal(r.itens.find(x=>x.codigo==='SU010').quantidade,1)
  assert.equal(r.itens.find(x=>x.codigo==='SU041').tratamento,'PINTURA PRETO')
  assert.equal(r.itens.find(x=>x.codigo==='SU039').tipo,'TUBULAR A TRATAR')
  assert.equal(r.itens.find(x=>x.codigo==='TMC').tratamento,'ANODIZADO FOSCO')
  assert.equal(r.itens.find(x=>x.codigo==='TMC').quantidade,2)
 }
 await assert.rejects(analisarPdfBarrasWVetro(Buffer.from('not PDF')),/PDF válido/)
 const route=fs.readFileSync('app/api/vendas/wvetro/barras/route.ts','utf8')
 assert.match(route,/relatorio\.numeroOrcamento!==ctx\.numeroWvetro/)
 assert.match(route,/status_compra:'necessidade'/)
 assert.match(route,/status_validacao:ed\.alterado\?'corrigido':'validado'/)
 assert.match(route,/\.eq\('empresa_id',ctx\.usuario\.empresa_id\)/)
 assert.match(route,/acao==='validar_lote'/)
 const central=fs.readFileSync('components/clientes/VendaObraCentral.tsx','utf8')
 assert.match(central,/VendaListaCorteWVetro/)
 assert.match(central,/VendaBarrasWVetro/)
 assert.match(central, /\{id:'materiais',label:'Materiais'\}/)
 assert.match(central,/aba==='materiais'&&<Box titulo="Lista de materiais para comprar/)
 assert.match(central,/VendaBarrasWVetro modo="lista"/)
 assert.match(central,/VendaBarrasWVetro modo="kanban"/)
 assert.match(central,/aba==='producao'&&<Box titulo="Produção/)
 assert.match(central,/editorCortesAberto&&\(\(\)=>/)
 // Materiais não deve ter Kanban de compras nem tratar cortes como barras comerciais.
 assert.match(central,/aba==='materiais'&&\(\(\)=>/)
 assert.match(central,/Materiais da obra · Conferência e separação/)
 assert.match(central,/Conferir estoque \/ PDF de/)
 assert.match(central,/selecionadosMateriais\.includes\(m\.id\)/)
 assert.match(central,/cotacaoPerfilWVetroBloqueada/)
 const materiaisBloco=central.slice(central.indexOf("{aba==='materiais'&&(()=>{"),central.indexOf("{aba==='tipologias'&&"))
 assert.doesNotMatch(materiaisBloco,/kanbanMateriais\.faltas|soltarMaterialNoKanban|moverMateriaisEmLote/)
 assert.match(central,/aba==='compras'&&<>/)
 const bars=fs.readFileSync('components/clientes/VendaBarrasWVetro.tsx','utf8')
 assert.match(bars,/modo==='lista'&&lista.length>0&&<div className="overflow-x-auto/)
 assert.match(bars,/\{qtd\(row.quantidade_barras\)\} BR/)
 assert.match(bars,/Total para compra/)
 assert.match(bars,/Validar e liberar para Compras/)
 assert.match(bars,/Conferir estoque \/ Imprimir PDF/)
 assert.match(bars,/modo==='kanban'&&lista.some\(x=>Boolean\(x.validado_em\)\)/)
 // Regra transversal de imagem em perfis/acessórios sem usar fotos genéricas.
 assert.match(bars,/row.imagem_url\?<img/)
 assert.match(bars,/Imagem pendente/)
 const api=fs.readFileSync('app/api/vendas/wvetro/barras/route.ts','utf8')
 assert.match(api,/\.eq\('empresa_id',ctx\.usuario\.empresa_id\)\.in\('codigo'/)
 assert.match(api,/imagem_url:imagens\.get\(normalizar\(row\.codigo\)\)/)
 assert.match(api,/acao==='validar_enviar_compras'/)
 assert.match(api,/\.is\('validado_em',null\)/)
 const corte=fs.readFileSync('components/clientes/VendaListaCorteWVetro.tsx','utf8')
 assert.match(corte,/m\.produto_id&&imagensPorProduto/)
 assert.match(corte,/m\.categoria==='acessorio'/)
 assert.match(corte,/Imagem pendente/)
 const pdfBarras=fs.readFileSync('app/compras/barras/[vendaId]/page.tsx','utf8')
 assert.match(pdfBarras,/Imagem pendente/)
 assert.match(pdfBarras,/Conferência de estoque/)
 assert.match(pdfBarras,/Estoque disponível/)
 const pdfCorte=fs.readFileSync('app/obras/[id]/materiais/pdf/page.tsx','utf8')
 assert.match(pdfCorte,/imagemDaPeca\(m\)/)
 assert.match(pdfCorte,/Imagem pendente/)
 assert.match(central,/Perfis cortados pertencem à Produção/)
 const migration=fs.readFileSync('supabase/migrations/20261013173835_wvetro_barras_compra_validacao_v1_20261013.sql','utf8')
 assert.match(migration,/unique\(venda_obra_id,chave_origem\)/)
 assert.match(migration,/venda_wvetro_barras_aprendizado/)
 console.log('PASS: relatório real WVetro #872 (quando disponível), escopo de compra seguro, acabamento, validação e aprendizado.')
}
run().catch(e=>{console.error(e);process.exitCode=1})